#ifndef EK_SUPPORT_XID_H
#define EK_SUPPORT_XID_H

#include <stdint.h>

/* The raw Unicode XID_Start / XID_Continue properties, as generated by
   tools/gen_xid.py. Clause 5.5.1 additionally admits '_' as a first
   character; that rule lives in the lexer, not here. */
int ek_xid_start(uint32_t cp);
int ek_xid_continue(uint32_t cp);

#endif
